using Mutagen.Bethesda; using Mutagen.Bethesda.Plugins; using SFRecordCompareEngine.Core.DTOs.Records; using SFRecordCompareEngine.Core.DTOs.Results; using SFRecordCompareEngine.Core.Helpers; using SFRecordCompareEngine.Core.Importers.Interfaces; using SFRecordCompareEngine.Core.Repositories.Interfaces;
namespace SFRecordCompareEngine.Core.Importers.Starfield;
public class MagicEffectImporter : ITypedRecordDetailImporter { private readonly IMagicEffectRepository Repository; public GameRelease GameRelease => GameRelease.Starfield; public RecordType RecordType => new(RecordTypeCatalog.MagicEffect.RecordID); public string TableName => RecordTypeCatalog.MagicEffect.TableName; public MagicEffectImporter(IMagicEffectRepository repository) { Repository = repository; } public void Import(object recordDTO, RecordTypeImportResultDTO resultDTO) { var record = (MagicEffectDTO)recordDTO; record.ImportedAtUTC = DateTime.UtcNow; Repository.Save(record); resultDTO.DetailRowsImported++; } }
